+              }
+            } catch (e) {
+              log(`fatal_error=${errText(e)}`);
+            } finally {
+              try {
+                await client.stop();
+              } catch (e) {
+                log(`stop_error=${errText(e)}`);
+              }
+            }
+            log(`sdk done utc=${nowUtc()}`);
+          PROBE_EOF
+
+      - name: Run the SDK probe from an empty directory with a fresh COPILOT_HOME
+        env:
+          GITHUB_TOKEN: ${{ github.token }}
+          PROBE_MODE: send
+          PROBE_SENDS: ${{ inputs.sends }}
+        run: |
+          export PROBE_COPILOT_HOME="$RUNNER_TEMP/pa08-copilot-home"
+          export PROBE_EMPTY_DIR="$RUNNER_TEMP/pa08-empty"
+          mkdir -p "$PROBE_COPILOT_HOME" "$PROBE_EMPTY_DIR"
+          cd "$PROBE_EMPTY_DIR"
+          echo "PROBE-PA08 job=sdk-omit start_utc=$(date -u +%Y-%m-%dT%H:%M:%SZ)"
+          timeout 300 node "$RUNNER_TEMP/pa08-sdk/probe.mjs" || echo "PROBE-PA08 job=sdk-omit node_exit=$?"
+
+  detect:
+    name: detect
+    if: ${{ github.event.sender.login == 'jambolo' && inputs.mode == 'detect' }}
+    runs-on: ubuntu-latest
+    timeout-minutes: 10
+    permissions:
+      copilot-requests: write
+    steps:
+      - name: Set up Node.js
+        uses: actions/setup-node@v7
+        with:
